head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > mergeCellsFixedRows]<br/>Body 의 고정 Row 영역에서 동일한 값이 연속되는 Cell 을 자동으로 병합하는 방식을 설정합니다.",
    "validation" : [
        "mergeCellsFixedRows 속성 설정 시 mergeCellsFixedCols 속성은 무시됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — fixedRow=2 + fixedColumn=1 그리드.
//  · col1(고정 Column) : 전 행 동일값 A → mergeCellsFixedCols('bycol') 단독 적용 시 비고정 Row 영역(행2~행5)이 세로 병합됨(FixedCols 단독 동작 입증).
//  · 행0~행1(고정 Row) : col2/col3 동일값(X,X) → mergeCellsFixedRows('bycol') 적용 시 고정 Row 영역만 세로 병합.
//  · 비고정 Row(행2~행5)의 col2/col3 은 서로 다른 값 → fixedRows 병합 대상 아님.
scwin.MERGE_DATA = [
    { "col1": "A", "col2": "X", "col3": "X", "col4": "1000" },
    { "col1": "A", "col2": "X", "col3": "X", "col4": "1000" },
    { "col1": "A", "col2": "c1", "col3": "c2", "col4": "2000" },
    { "col1": "A", "col2": "d1", "col3": "d2", "col4": "3000" },
    { "col1": "A", "col2": "e1", "col3": "e2", "col4": "4000" },
    { "col1": "A", "col2": "f1", "col3": "f2", "col4": "5000" }
];



// comp 생성 : fixedRow=2 (행0~행1 고정) + fixedColumn=1 (col1 고정) 그리드 1개를 동적 생성한다.
//  ★ 병합 속성은 생성 attribute 로 주지 않고, 핸들러에서 단계적으로 적용하여 '무시' 발동 경로를 시연한다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리 (동일 id 재생성 무시 방지)
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="fixedRow=2(행0~행1 고정) + fixedColumn=1(col1 고정). col1 은 전 행 동일값 A. 버튼으로 ① mergeCellsFixedCols(bycol) 단독 적용(비고정 Row 영역 col1 세로병합) → ② mergeCellsFixedRows(bycol) 추가+재병합 시 mergeCellsFixedCols 가 never 로 리셋되어 무시(고정 Row 영역만 병합) 를 확인"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    // fixedRow=2 + fixedColumn=1
    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id, fixedRow: 2, fixedColumn: 1 });

    // target 생성 (병합 속성 미부여)
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:420px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCellsFixedRows sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column1" value="col1"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column2" value="col2"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column3" value="col3"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column4" value="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 비고정 Row 영역(행2 이상)의 col1(고정 Column) 세로병합 여부 확인
//  - fixedColumn 영역 td 는 _fixedColumnDiv 안에 위치. id 는 target1_cell_{row}_{col}.
//  - 화면에 표시되는(흡수되지 않은) td 의 rowSpan 으로 판정.
scwin.isNonFixedRowCol1Merged = function () {
    let gid = target1.id;
    let tds = document.querySelectorAll("td[id*='" + gid + "_cell_']");
    let merged = false;
    for (let i = 0; i < tds.length; i++) {
        let td = tds[i];
        if (getComputedStyle(td).display === 'none' || td.offsetParent === null) continue;
        let m = td.id.match(/_cell_(\d+)_(\d+)/);
        if (!m) continue;
        let r = Number(m[1]), c = Number(m[2]);
        let rs = td.rowSpan || 1;
        // col1(c===0) 이고 시작 행이 비고정 Row(행2 이상)이며 세로병합(rowSpan>1)
        if (c === 0 && r >= 2 && rs > 1) merged = true;
    }
    return merged;
}



// '무시' 발동 확인 핸들러
scwin.btn_checkIgnore_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let grid = $p.getComponentById("target1");

    // ① mergeCellsFixedCols('bycol') 단독 적용 → 비고정 Row 영역(col1)이 세로 병합되어야 함
    grid.mergeCellsFixedCols("bycol");
    grid.dynamicMergeHTML();

    let optColsStep1 = grid.options.mergeCellsFixedCols;
    let col1MergedStep1 = scwin.isNonFixedRowCol1Merged();
    bottom.setReturnValue("① mergeCellsFixedCols('bycol') 단독 적용 → options.mergeCellsFixedCols : " + optColsStep1 + " / 비고정 Row 영역 col1 세로병합 : " + col1MergedStep1 + " (FixedCols 단독 동작 입증)");

    // ② mergeCellsFixedRows('bycol') 추가 설정 후 두 속성을 함께 둔 상태에서 재병합(_mergeRefresh)
    //    → mergeCellsFixedRows() 가 내부 mergeClear 로 options.mergeCellsFixedCols 를 'never' 로 리셋
    //    → 재병합 시 mergeCellsFixedRows 만 적용(고정 Row 영역만 병합), mergeCellsFixedCols 는 무시
    grid.options.mergeCellsFixedRows = "bycol";
    grid._mergeRefresh();
    grid.dynamicMergeHTML();

    let optColsStep2 = grid.options.mergeCellsFixedCols;
    let optRowsStep2 = grid.options.mergeCellsFixedRows;
    let col1MergedStep2 = scwin.isNonFixedRowCol1Merged();
    bottom.setReturnValue("② mergeCellsFixedRows('bycol') 설정 + 재병합 → options.mergeCellsFixedCols : " + optColsStep2 + " / options.mergeCellsFixedRows : " + optRowsStep2 + " / 비고정 Row 영역 col1 세로병합 : " + col1MergedStep2);

    // ③ 판정 : mergeCellsFixedRows 설정 시 mergeCellsFixedCols 가 never 로 리셋(무시) + 비고정 Row col1 병합 사라짐
    let ignored = (optColsStep2 === "never") && (col1MergedStep2 === false);
    bottom.setReturnValue("mergeCellsFixedRows 설정 시 mergeCellsFixedCols 무시 : " + ignored);
}
